package com.rork.vitahero.data

import com.rork.vitahero.Config
import io.github.jan-tennert.supabase.createSupabaseClient
import io.github.jan-tennert.supabase.postgrest.Postgrest
import kotlinx.serialization.json.Json

object SupabaseService {
    val client by lazy {
        createSupabaseClient(
            supabaseUrl = Config.EXPO_PUBLIC_SUPABASE_URL,
            supabaseKey = Config.EXPO_PUBLIC_SUPABASE_ANON_KEY
        ) {
            install(Postgrest) {
                defaultSerializer = kotlinx.serialization.json.Json {
                    ignoreUnknownKeys = true
                    isLenient = true
                    coerceInputValues = true
                }
            }
        }
    }
}

