                    supabase.upsertGrowthPoint(GrowthPointDto(
                        id = "${kid.id}_gp_${gp.label.replace(" ", "_")}",
                        kidId = kid.id,
                        label = gp.label,
                        height = gp.height.toDouble(),
                        weight = gp.weight.toDouble(),
                    ))
                }
            }
        } catch (_: Exception) { /* Supabase sync is best-effort */ }
    }
}

