package com.rork.vitahero.data

import io.github.jan-tennert.supabase.postgrest.postgrest
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.util.UUID

/**
 * Bridges the Android app to Supabase Postgres.
 * All network calls run on [Dispatchers.IO].
 * Uses the supabase-kt 3.x API with direct client.from() calls.
 */
class SupabaseRepository {

    private val client get() = SupabaseService.client

    // ─── Profiles ──────────────────────────────────────────────

    suspend fun upsertProfile(dto: ProfileDto) = onIo {
        client.from("profiles").upsert(dto)
    }

    suspend fun fetchProfile(profileId: String): ProfileDto? = onIo {
        client.from("profiles")
            .select { filter { eq("id", profileId) } }
            .decodeSingleOrNull<ProfileDto>()
    }

    // ─── Kids ──────────────────────────────────────────────────

    suspend fun fetchKids(profileId: String): List<KidDto> = onIo {
        client.from("kids")
            .select { filter { eq("profile_id", profileId) } }
            .decodeList<KidDto>()
    }

    suspend fun upsertKid(dto: KidDto) = onIo {
        client.from("kids").upsert(dto)
    }

    suspend fun upsertKids(dtos: List<KidDto>) = onIo {
        dtos.forEach { client.from("kids").upsert(it) }
    }

    suspend fun deleteKid(kidId: String) = onIo {
        client.from("kids").delete { filter { eq("id", kidId) } }
    }

    // ─── Camps ─────────────────────────────────────────────────

    suspend fun fetchCamps(profileId: String): List<CampDto> = onIo {
        client.from("camps")
            .select { filter { eq("profile_id", profileId) } }
            .decodeList<CampDto>()
    }

    suspend fun upsertCamp(dto: CampDto) = onIo {
        client.from("camps").upsert(dto)
    }

    suspend fun upsertCamps(dtos: List<CampDto>) = onIo {
        dtos.forEach { client.from("camps").upsert(it) }
    }

    // ─── Appointments ──────────────────────────────────────────

    suspend fun fetchAppointments(profileId: String): List<AppointmentDto> = onIo {
        client.from("appointments")
            .select { filter { eq("profile_id", profileId) } }
            .decodeList<AppointmentDto>()
    }

    suspend fun upsertAppointment(dto: AppointmentDto) = onIo {
        client.from("appointments").upsert(dto)
    }

    suspend fun deleteAppointment(appointmentId: String) = onIo {
        client.from("appointments").delete { filter { eq("id", appointmentId) } }
    }

    // ─── Meals ─────────────────────────────────────────────────

    suspend fun fetchAllMeals(profileId: String): List<MealItemDto> = onIo {
        client.from("meal_items")
            .select { filter { eq("profile_id", profileId) } }
            .decodeList<MealItemDto>()
    }

    suspend fun upsertMeal(dto: MealItemDto) = onIo {
        client.from("meal_items").upsert(dto)
    }

    suspend fun upsertMeals(dtos: List<MealItemDto>) = onIo {
        dtos.forEach { client.from("meal_items").upsert(it) }
    }

    // ─── Growth Points ─────────────────────────────────────────

    suspend fun fetchGrowthPoints(kidId: String): List<GrowthPointDto> = onIo {
        client.from("growth_points")
            .select { filter { eq("kid_id", kidId) } }
            .decodeList<GrowthPointDto>()
    }

    suspend fun upsertGrowthPoint(dto: GrowthPointDto) = onIo {
        client.from("growth_points").upsert(dto)
    }

    // ─── Streaks ───────────────────────────────────────────────

    suspend fun fetchStreak(kidId: String): StreakDto? = onIo {
        client.from("streaks")
            .select { filter { eq("kid_id", kidId) } }
            .decodeSingleOrNull<StreakDto>()
    }

    suspend fun upsertStreak(dto: StreakDto) = onIo {
        client.from("streaks").upsert(dto)
    }

    // ─── Co-Parents ────────────────────────────────────────────

    suspend fun fetchCoParents(profileId: String): List<CoParentDto> = onIo {
        client.from("co_parents")
            .select { filter { eq("profile_id", profileId) } }
            .decodeList<CoParentDto>()
    }

    suspend fun upsertCoParent(dto: CoParentDto) = onIo {
        client.from("co_parents").upsert(dto)
    }

    // ─── Helpers ───────────────────────────────────────────────

    fun newId(): String = UUID.randomUUID().toString().take(12)

    private suspend fun <T> onIo(block: suspend () -> T): T =
        withContext(Dispatchers.IO) { block() }
}

